import React, { useRef, useState, useEffect } from "react";
import "./VideoCarousel.css";

export default function VideoCarousel({ videoList }) {
  const videos = videoList || [
    "/assets/banner1.mp4",
    "/assets/banner2.mp4",
    "/assets/banner3.mp4",
    "/assets/banner4.mp4",
  ];

  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);
  const [showButton, setShowButton] = useState(false);
  const videoRef = useRef(null);

  // Show play/pause button on click
  const handleVideoClick = () => {
    setShowButton(true);
    setTimeout(() => setShowButton(false), 2000);
  };

  // Play/Pause toggle
  const togglePlay = () => {
    const video = videoRef.current;
    if (!video) return;
    if (video.paused) {
      video.play();
      setIsPlaying(true);
      setShowButton(false);
    } else {
      video.pause();
      setIsPlaying(false);
      setShowButton(true);
    }
  };

  // Manual navigation
  const handlePrev = () => {
    setCurrentIndex((prev) => (prev - 1 + videos.length) % videos.length);
  };

  const handleNext = () => {
    setCurrentIndex((prev) => (prev + 1) % videos.length);
  };

  // Auto slide every 10 sec
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % videos.length);
    }, 10000);
    return () => clearInterval(timer);
  }, [videos.length]);

  // When video changes
  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.play().catch(() => {});
      setIsPlaying(true);
      setShowButton(false);
    }
  }, [currentIndex]);

  return (
    <div className="carousel-container" onClick={handleVideoClick}>
      <div
        className="carousel-track"
        style={{ transform: `translateX(-${currentIndex * 100}%)` }}
      >
        {videos.map((src, i) => (
          <video
            key={i}
            ref={i === currentIndex ? videoRef : null}
            src={src}
            muted
            autoPlay={i === currentIndex}
            loop
            playsInline
            className="carousel-video"
          />
        ))}
      </div>

      {/* Prev / Next buttons */}
      <button className="vc-btn prev" onClick={handlePrev}>
        ⟨
      </button>
      <button className="vc-btn next" onClick={handleNext}>
        ⟩
      </button>

      {/* Play / Pause overlay */}
      {showButton && (
        <button className="play-overlay" onClick={togglePlay}>
          {isPlaying ? "❚❚" : "►"}
        </button>
      )}

      {/* Index indicator */}
      <div className="video-index">
        {currentIndex + 1}/{videos.length}
      </div>
    </div>
  );
}
